function evaluate(c:any){const before=JSON.stringify(c),result=api.evaluate(c);assert.equal(bytesSha(JSON.stringify(c)),bytesSha(before),'Evaluation is pure');return result;}
function status(c:any,id:string,entryId=feat.id){const before=JSON.stringify(c),result=api.reviewedObservantStatus(c,id,entryId);assert.equal(bytesSha(JSON.stringify(c)),bytesSha(before),'Status is pure');return result;}
function reject(c:any,fn:()=>void){const before=JSON.stringify(c);assert.throws(fn);assert.equal(bytesSha(JSON.stringify(c)),bytesSha(before),'Rejected mutation is atomic');}
const activate=(c:any,ability='int',level=4,catalog=appCatalog)=>{const id=select(c,level),before=json(c);delete before.reviewedObservant;api.setReviewedObservantIntent(c,id,feat.id,intent(ability),catalog);const after=json(c);delete after.reviewedObservant;assert.equal(hash(after),hash(before),'Confirmation writes only its independent owned domain');assert.equal(status(c,id).active,true);return id;};
function reopen(c:any,linked=false){const before=JSON.stringify(c),payload=json(linked?api.exportLinkedOwlbear(c,evaluate(c)):api.exportCharacter(c)),inputBefore=JSON.stringify(payload),loaded=linked?{character:api.importOwlbear(payload),repaired:[]}:api.readCharacter(payload);assert.deepEqual(loaded.repaired,[]);assert.equal(bytesSha(JSON.stringify(c)),bytesSha(before),'Export is pure');assert.equal(bytesSha(JSON.stringify(payload)),bytesSha(inputBefore),'Import is pure');assert.deepEqual(loaded.character.reviewedObservant,c.reviewedObservant);assert.deepEqual(preserve(loaded.character),preserve(c));return loaded.character;}
function check(mechanism:string,label:string,fn:()=>void){try{fn();}catch(error){throw Error(label,{cause:error});}steps.push({mechanism,label,passed:true});}
check('source-authentication','Actual PHB and modern source records retain separate canonical identities and exact clause digests',()=>{assert(api.reviewedObservantRule(feat));assert.equal(api.reviewedObservantRule(modern),undefined);assert.equal(api.reviewedModernObservantRule(modern),true);assert.equal(api.reviewedObservantIdentity(feat),true);assert.equal(api.reviewedObservantIdentity(modern),false);for(const text of [...rawFeat.entries[1].items,JSON.stringify(rawModern.entries),baselineNode.entries[2].text,'','abc','中文🙂'])assert.equal(api.sourceTextSha256(text),bytesSha(text),'Actual browser-safe UTF8 checksum matches independent Node SHA256');});
check('app-directory','Actual mixed-edition directory and authored App seed allow one PHB confirmation without name-only poisoning',()=>{const phb=appCatalog.filter((e:any)=>e.id===feat.id),xphb=appCatalog.filter((e:any)=>e.id===modern.id);assert.equal(phb.length,1);assert.equal(xphb.length,1);const c=baseCard(),id=activate(c),d=evaluate(c);assert.equal(status(c,id).active,true);assert.equal(d.abilities.int,20);assert.equal(d.passive,15);assert.equal(d.passiveInvestigation,20);assert.equal(d.skills.perception.value,0);assert.equal(d.skills.investigation.value,5);});
