 let cached:any,loads=0,batches:any[]=[];const scope='bounded-observant:'+catalogScope,common={scope,signal:new AbortController().signal,onProgress:()=>{},onSources:()=>{},onBatch:(rows:any[])=>batches.push(...rows)};
