for(const perception of [-4,0,3,5])for(const investigation of [-3,0,4,5])check('manual-skill-offset',`Signed authored offsets P${perception}/I${investigation} remain separate from owned passive5`,()=>{const c=baseCard();c.skillBonuses={perception,investigation};const manual=preserve(c);activate(c);const d=evaluate(c);assert.equal(d.skills.perception.value,perception);assert.equal(d.skills.investigation.value,5+investigation);assert.equal(d.passive,15+perception);assert.equal(d.passiveInvestigation,20+investigation);assert.deepEqual(preserve(c),manual);});
